diff:
A result.json
A tmp/corr.ps1
A tmp/stats.ps1

--- result.json ---
{
  "avg_fps": 137.29,
  "low_1pct_fps": 45.35,
  "cause": "The GPU's PCIe link drops into ASPM L1 sleep roughly every 4 s (sensors.csv shows gpu_pcie_link_state=L1 at t=2,6,10,...,58). Each L1 entry aligns with a ~240 ms hitch cluster in presentmon.csv (15 clusters at t=2.4, 6.4, ..., 58.4, frame times 21-23 ms vs ~7 ms normal), which drags the 1% low to ~45 fps while the average stays ~137 fps. The PCIe ASPM root-port setting for the GPU (pcie_aspm_rp1_gpu=L1) is what allows the link to enter L1; the Defender/MsMpEng spike at t=43-45 (DPC 400-455 us, disk 80-94%) is a secondary, smaller source of jitter but does not produce the periodic hitches.",
  "changes": [
    {
      "setting": "pcie_aspm_rp1_gpu",
      "from": "L1",
      "to": "disabled"
    },
    {
      "setting": "defender_exclusions",
      "from": [],
      "to": [
        "C:\\Arena\\Arena.exe"
      ]
    }
  ]
}

--- tmp/corr.ps1 ---
$pm = '<WORKSPACE>\capture\presentmon.csv'
$sn = '<WORKSPACE>\capture\sensors.csv'
$lines = Get-Content $pm
$rows = @()
for ($i = 1; $i -lt $lines.Count; $i++) {
  if (-not $lines[$i].Trim()) { continue }
  $c = $lines[$i].Split(',')
  $rows += ,@([double]$c[7], [double]$c[8])
}
# hitch clusters: contiguous runs of mbp > 15ms
$clusters = @()
$start = -1
for ($i = 0; $i -lt $rows.Count; $i++) {
  if ($rows[$i][1] -gt 15.0) {
    if ($start -lt 0) { $start = $i }
  } else {
    if ($start -ge 0) { $clusters += ,@($rows[$start][0], $rows[$i-1][0]); $start = -1 }
  }
}
if ($start -ge 0) { $clusters += ,@($rows[$start][0], $rows[$rows.Count-1][0]) }
Write-Host "hitch clusters (t_start..t_end):"
foreach ($cl in $clusters) { Write-Host ("  {0:0.000} .. {1:0.000}" -f $cl[0], $cl[1]) }
# sensor L1 and defender rows
$sens = Get-Content $sn
Write-Host "sensor L1 / defender rows:"
foreach ($l in $sens[1..($sens.Count-1)]) {
  if (-not $l.Trim()) { continue }
  $c = $l.Split(',')
  if ($c[4] -eq 'L1' -or $c[8] -ne 'Arena.exe') { Write-Host ("  t={0} link={1} top={2} dpc={3} disk={4}" -f $c[0], $c[4], $c[8], $c[6], $c[7]) }
}
# correlation: for each cluster, which sensor second(s) does it fall in
Write-Host "cluster -> sensor seconds:"
foreach ($cl in $clusters) {
  $a = [int][Math]::Floor($cl[0]); $b = [int][Math]::Ceil($cl[1])
  $hits = @()
  foreach ($l in $sens[1..($sens.Count-1)]) {
    if (-not $l.Trim()) { continue }
    $c = $l.Split(',')
    $t = [int]$c[0]
    if ($t -ge $a -and $t -le $b) { $hits += ("t{0}:{1}/{2}" -f $t, $c[4], $c[8]) }
  }
  Write-Host ("  {0:0.000}..{1:0.000} -> {2}" -f $cl[0], $cl[1], ($hits -join ' '))
}

--- tmp/stats.ps1 ---
$path = '<WORKSPACE>\capture\presentmon.csv'
$lines = Get-Content $path
$mbp = [double[]]@()
$mbd = [double[]]@()
foreach ($l in $lines[1..($lines.Count-1)]) {
  if (-not $l.Trim()) { continue }
  $c = $l.Split(',')
  $mbp += [double]$c[8]
  $mbd += [double]$c[9]
}
$n = $mbp.Count
$mean = ($mbp | Measure-Object -Average).Average
$avgFps = 1000.0 / $mean
function Pct([double[]]$a, [double]$p) {
  $s = $a | Sort-Object
  $idx = [Math]::Ceiling($p/100.0 * $s.Count) - 1
  if ($idx -lt 0) { $idx = 0 }
  return $s[$idx]
}
$p99 = Pct $mbp 99
$low1 = 1000.0 / $p99
$p99d = Pct $mbd 99
Write-Host "frames=$n mean_ms=$mean avg_fps=$avgFps p99_ms=$p99 low1pct_fps=$low1 p99_display_ms=$p99d"
# hitch rows: frame time > 3x median
$med = Pct $mbp 50
$big = 0
for ($i = 1; $i -lt $n; $i++) {
  if ($mbp[$i] -gt 3*$med) {
    $big++
    if ($big -le 15) { Write-Host ("row {0}: time_s={1} mbp={2} mbd={3}" -f ($i+1), $lines[$i].Split(',')[7], $mbp[$i], $mbd[$i]) }
  }
}
Write-Host "big_frames(>3x median)=$big median_ms=$med"
